import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Tailoring","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/tailoring.md","filePath":"en/guide/professions/tailoring.md"}'),r={name:"en/guide/professions/tailoring.md"};function o(s,e,l,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="tailoring" tabindex="-1">Tailoring <a class="header-anchor" href="#tailoring" aria-label="Permalink to &quot;Tailoring&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/en/game-design/professions/tailoring.html">full design specification</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Tailoring works with leather, cloth, fibers and flexible protection.</li><li>Fitting, stitching, repair and assessment give it field value beyond clothing production.</li><li>Materials, fashion and learned methods support specialization; harvesting and layering remain Proposed.</li></ul><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Tailoring is the craft of flexible materials: leather, fur, cloth, fibers, padding, thread, garments and flexible armor. Harvesting, preservation, processing, grading, cutting, assembly, fitting and finishing should each serve a meaningful purpose.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>Fitting, field stitching, repairs and material assessment make it useful beyond clothing production. Correct adjustment and maintenance should reduce relevant penalties without becoming a flat armor bonus. Leather and cloth can protect in ways distinct from plate.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>The Material/Tailoring Journal can include hide zones, treatments and construction knowledge. Damage to a creature may affect harvested hides. Anatomy and Animal Lore are proposed partners in harvesting; a separate skinning skill is not settled. Fashion is also a legitimate path: cuts, dyes, embroidery and cultural or guild styles can carry identity and status.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progression and related crafts <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Permalink to &quot;Progression and related crafts&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/overview.html">Shared learning and production</a> apply, with more capable material work as skill and knowledge grow. <a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a> may supply treatments, pigments and mordants; <a href="/Syrolands-Public/en/guide/professions/carpentry.html#bowmaking-and-fletching">Carpentry’s Bowmaking path</a> can use optional tailoring support. Harvest, fitting and layering rules remain proposed.</p><p><a href="/Syrolands-Public/en/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/en/game-design/professions/tailoring.html">Full design specification</a></p>',13)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
